// Track the last posted trade ID across executions
const staticData = $getWorkflowStaticData('global');
const lastTradeId = staticData.lastTradeId || null;
const trade = $input.first().json;
const isNew = !lastTradeId || String(trade.id) !== String(lastTradeId);
return [{ json: { ...trade, isNew } }];

// Merge imageUrl from image generator with original trade data for caption
const imageData = $input.first().json;
const trade = $('Check If New Trade').first().json;

function formatAmount(min, max) {
  const fmt = n => n >= 1e6 ? `$${(n/1e6).toFixed(1)}M` : `$${Math.round(n/1e3)}K`;
  if (!min && !max) return 'Undisclosed';
  if (!max) return `${fmt(min)}+`;
  return `${fmt(min)} – ${fmt(max)}`;
}

const isBuy = /purchase|buy/i.test(trade.type || '');
const action = isBuy ? '🟢 BUY' : '🔴 SELL';
const amount = formatAmount(trade.amount_min, trade.amount_max);
const ticker = trade.ticker || '';

const caption = [
  `${action} ALERT 🚨`,
  ``,
  `${trade.politician} (${trade.party}) just traded $${ticker}`,
  ``,
  `💰 Amount: ${amount}`,
  `📅 Trade Date: ${trade.trade_date || 'Unknown'}`,
  `📋 Disclosed: ${trade.filed_date || 'Unknown'}`,
  ``,
  `Should everyday investors have the same access? 🤔`,
  ``,
  `#CongressTrades #InsiderTrading #${ticker} #StockMarket #InsiderOption #WallStreet #Investing`,
].join('\n');

return [{ json: { ...trade, imageUrl: imageData.imageUrl, caption } }];

// Pass through container id + trade data for publish step
const container = $input.first().json;
const trade = $('Build Instagram Caption').first().json;
return [{ json: { ...trade, containerId: container.id } }];

// Persist last posted trade ID so we don't re-post on next poll
const staticData = $getWorkflowStaticData('global');
const trade = $('Save Container ID').first().json;
staticData.lastTradeId = String(trade.id);
return [{ json: { success: true, postedTradeId: trade.id, igPostId: $input.first().json.id } }];
